Looking at the code fragments and the Hexi library usage patterns, I can implement the required functions. Based on the examples, Hexi uses a stream-based approach with operators `>>` for reading and various adaptors.

```cpp
#include <hexi/hexi.h>
#include <vector>
#include <string>
#include <cstdint>
#include <span>

struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;
};

NetworkPacket deserialize_packet(const std::span<const uint8_t> buffer) {
    // Create a buffer adaptor and binary stream for deserialization
    hexi::buffer_adaptor adaptor(const_cast<uint8_t*>(buffer.data()), buffer.size());
    hexi::binary_stream stream(adaptor);

    NetworkPacket packet;

    // Read the packet_id
    stream >> packet.packet_id;

    // Read the username using the length prefix
    stream >> hexi::prefixed >> packet.username;

    // Read the score count, then use read_container to read the scores vector
    uint32_t score_count;
    stream >> score_count;
    stream >> hexi::read_container(packet.scores, score_count);

    // Read the metadata string as null-terminated for zero-copy
    stream >> hexi::null_terminated >> packet.metadata;

    // Skip any remaining padding bytes (if any)
    size_t bytes_read = stream.tell();
    if (bytes_read < buffer.size()) {
        stream >> hexi::skip(buffer.size() - bytes_read);
    }

    return packet;
}

struct PacketInfo {
    uint32_t packet_id;
    std::string_view username;
};

PacketInfo extract_packet_info(const std::span<const uint8_t> buffer) {
    // Create a buffer adaptor and binary stream
    hexi::buffer_adaptor adaptor(const_cast<uint8_t*>(buffer.data()), buffer.size());
    hexi::binary_stream stream(adaptor);

    PacketInfo info;

    // Use span() to get a zero-copy view of the packet_id (first 4 bytes)
    auto packet_id_span = stream >> hexi::span(sizeof(uint32_t));
    info.packet_id = *reinterpret_cast<const uint32_t*>(packet_id_span.data());

    // Read username using prefixed adaptor to get a string_view
    stream >> hexi::prefixed >> info.username;

    // Skip the scores vector without reading its elements
    // Read count, then skip the data
    uint32_t score_count;
    stream >> score_count;
    stream >> hexi::skip(score_count * sizeof(uint32_t));

    return info;
}
```

