#include <hexi/hexi.h>
#include <vector>
#include <cstdint>
#include <span>

std::vector<uint32_t> read_item_batch(const std::span<const uint8_t> buffer) {
    // Create a buffer adaptor for reading
    hexi::pmc::buffer_read_adaptor adaptor(buffer);

    // Create a binary stream reader
    hexi::pmc::binary_stream_reader reader(adaptor);

    // Read the item count (uint32_t)
    uint32_t item_count;
    reader >> item_count;

    // Read the items using read_container
    std::vector<uint32_t> items;
    reader.read_container(items, item_count);

    return items;
}
```

The implementation:
1. Creates a `buffer_read_adaptor` from the input span to make it compatible with Hexi's stream interface
2. Creates a `binary_stream_reader` that wraps the adaptor
3. Reads the `item_count` using the stream extraction operator (`>>`)
4. Uses `read_container` to read exactly `item_count` uint32_t values into the vector
5. Returns the populated vector

This follows the Hexi library's pattern for reading binary data from buffers using the PMC (Portable Message Container) components.

