    auto result = read_buffer_data(source, 5);

    EXPECT_EQ(5, result.size());
    EXPECT_EQ(1, result[0]);
    EXPECT_EQ(5, result[4]);
}

TEST(BufferAdaptor, WriteData) {
    std::vector<uint8_t> dest;
    std::vector<uint8_t> source = {10, 20, 30, 40};

    write_buffer_data(dest, source);

    EXPECT_EQ(source.size(), dest.size());
    EXPECT_EQ(source, dest);
}

TEST(BufferAdaptor, ReadWriteRoundTrip) {
    std::vector<uint8_t> original = {100, 200, 150, 250};
    std::vector<uint8_t> buffer;

    write_buffer_data(buffer, original);
    auto read_back = read_buffer_data(buffer, original.size());

    EXPECT_EQ(original, read_back);
}

