bool write_data_with_check(std::vector<uint8_t>& buffer, uint32_t header, const std::vector<uint32_t>& items) {
    // Create a buffer adaptor to manage the buffer
    hexi::buffer_adaptor adaptor(buffer);

    // Calculate required space:
    // - sizeof(uint32_t) for header
    // - sizeof(uint32_t) for container size
    // - items.size() * sizeof(uint32_t) for all items
    std::size_t required_space = sizeof(uint32_t) + sizeof(uint32_t) + (items.size() * sizeof(uint32_t));

    // Check if there's enough space available
    if (adaptor.space() < required_space) {
        return false;
    }

    // Get the write pointer
    auto write_ptr = adaptor.write_ptr();

    // Create a binary stream for writing
    hexi::binary_stream stream(write_ptr, adaptor.space());

    // Write the header
    stream.write(header);

    // Write the container data (vector of items)
    stream.write_container(items);

    // Update the buffer adaptor's write position
    adaptor.commit(stream.wcount());

    return true;
}

