```cpp
#include <hexi/hexi.h>
#include <cstdint>
#include <span>

struct PacketHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    // Create a buffer_adaptor from the span
    hexi::pmc::buffer_adaptor adaptor(buffer);

    // Get the read pointer
    const auto* read_ptr = adaptor.read_ptr();

    // Check available data (header size is 8 bytes: 4 + 2 + 2)
    constexpr size_t header_size = sizeof(PacketHeader);
    if (adaptor.size() < header_size) {
        throw std::runtime_error("Insufficient data for header");
    }

    // Create a binary_stream for zero-copy view of the header
    hexi::binary_stream stream(read_ptr, header_size);

    // Read header fields using zero-copy operations
    PacketHeader header;
    header.magic = stream.get<uint32_t>();
    header.version = stream.get<uint16_t>();
    header.flags = stream.get<uint16_t>();

    return header;
}
```

