output.text:
Here's the complete implementation demonstrating the block allocator's free list management:

```cpp
#include <hexi/allocators/block_allocator.h>
#include <cstdint>
#include <iostream>
#include <vector>

// Note: push() and pop() are private, but we can observe their behavior
// through allocate() and deallocate() operations
template<size_t element_count = 10>
void demonstrate_block_allocator_behavior() {
    // Create a block_allocator for int with element_count elements
    hexi::block_allocator<int, element_count> allocator;

    std::cout << "=== Demonstrating Block Allocator Free List Behavior ===" << std::endl;
    std::cout << "Block allocator created with capacity: " << element_count << std::endl;
    std::cout << std::endl;

    // Initially, all blocks are in the free list (linked together)
    // The free list is built during initialization with all blocks linked

    std::cout << "Phase 1: Allocating blocks (internally calls pop())" << std::endl;
    std::vector<int*> allocated_blocks;

    // Allocate several blocks - each allocate() internally calls pop()
    // to remove the head block from the free list
    for(size_t i = 0; i < 5; ++i) {
        int* block = allocator.allocate(static_cast<int>(i * 100));
        allocated_blocks.push_back(block);
        std::cout << "  Allocated block " << i << " at address: " << block 
                  << ", value: " << *block << std::endl;
    }

    std::cout << std::endl;
    std::cout << "Phase 2: Deallocating blocks (internally calls push())" << std::endl;

    // Deallocate blocks in different order - each deallocate() internally calls push()
    // to add the block back to the head of the free list (LIFO behavior)
    std::cout << "  Deallocating block 2..." << std::endl;
    allocator.deallocate(allocated_blocks[2]);

    std::cout << "  Deallocating block 0..." << std::endl;
    allocator.deallocate(allocated_blocks[0]);

    std::cout << "  Deallocating block 4..." << std::endl;
    allocator.deallocate(allocated_blocks[4]);

    std::cout << std::endl;
    std::cout << "Phase 3: Reallocating (demonstrates LIFO order)" << std::endl;

    // When we allocate again, we get blocks in LIFO order (Last In, First Out)
    // The most recently deallocated block (4) will be returned first
    std::cout << "  Allocating new block (should reuse block 4)..." << std::endl;
    int* reused1 = allocator.allocate(999);
    std::cout << "    Got address: " << reused1 << std::endl;

    std::cout << "  Allocating new block (should reuse block 0)..." << std::endl;
    int* reused2 = allocator.allocate(888);
    std::cout << "    Got address: " << reused2 << std::endl;

    std::cout << "  Allocating new block (should reuse block 2)..." << std::endl;
    int* reused3 = allocator.allocate(777);
    std::cout << "    Got address: " << reused3 << std::endl;

    std::cout << std::endl;
    std::cout << "Phase 4: Exhausting the allocator" << std::endl;

    // Allocate remaining blocks from the preallocated pool
    std::vector<int*> more_blocks;
    for(size_t i = 0; i < element_count - 5; ++i) {
        int* block = allocator.allocate(static_cast<int>(i));
        more_blocks.push_back(block);
    }
    std::cout << "  Allocated all remaining blocks from pool" << std::endl;

    // Next allocation will fall back to system allocator (new)
    std::cout << "  Allocating beyond pool capacity (falls back to new)..." << std::endl;
    int* overflow_block = allocator.allocate(12345);
    std::cout << "    Overflow block at address: " << overflow_block 
              << ", value: " << *overflow_block << std::endl;

    // Cleanup
    allocator.deallocate(allocated_blocks[1]);
    allocator.deallocate(allocated_blocks[3]);
    allocator.deallocate(reused1);
    allocator.deallocate(reused2);
    allocator.deallocate(reused3);
    for(auto* block : more_blocks) {
        allocator.deallocate(block);
    }
    allocator.deallocate(overflow_block);

    std::cout << std::endl;
    std::cout << "=== Summary ===" << std::endl;
    std::cout << "The free list uses LIFO (stack) behavior:" << std::endl;
    std::cout << "  - push() adds blocks to the head of the list" << std::endl;
    std::cout << "  - pop() removes and returns the head block" << std::endl;
    std::cout << "  - Deallocated blocks are reused in reverse order" << std::endl;
}
```

This implementation demonstrates:

1. **Initial state**: The allocator pre-allocates a slab and builds a linked free list
2. **Allocation (pop)**: Each `allocate()` internally calls `pop()` to remove the head block
3. **Deallocation (push)**: Each `deallocate()` internally calls `push()` to add the block back to the head
4. **LIFO behavior**: Blocks are reused in Last-In-First-Out order
5. **Overflow handling**: When the pool is exhausted, it falls back to `new`

