Looking at the code fragments, I can see how the `hexi::file_buffer` class is used. Based on the test examples, I can implement the required functions:

```cpp
#include <hexi/file_buffer.h>
#include <vector>
#include <cstdint>
#include <filesystem>

std::vector<uint8_t> read_file_data(const std::filesystem::path& file_path, size_t bytes_to_read) {
    // Open file buffer for reading
    hexi::file_buffer buffer(file_path);

    if (!buffer) {
        return {}; // Return empty vector if file open failed
    }

    // Create destination buffer
    std::vector<uint8_t> data(bytes_to_read);

    // Read data from file
    buffer.read(data.data(), bytes_to_read);

    if (!buffer) {
        return {}; // Return empty vector if read failed
    }

    return data;
}

std::vector<uint8_t> preview_file_data(const std::filesystem::path& file_path, size_t bytes_to_preview) {
    // Open file buffer for reading
    hexi::file_buffer buffer(file_path);

    if (!buffer) {
        return {}; // Return empty vector if file open failed
    }

    // Create destination buffer
    std::vector<uint8_t> data(bytes_to_preview);

    // Preview data without advancing read pointer
    buffer.peek(data.data(), bytes_to_preview);

    if (!buffer) {
        return {}; // Return empty vector if peek failed
    }

    return data;
}

void write_file_data(const std::filesystem::path& file_path, const std::vector<uint8_t>& data) {
    // Open file buffer for writing
    hexi::file_buffer buffer(file_path, hexi::file_buffer::mode::write);

    if (!buffer) {
        return; // Exit if file open failed
    }

    // Write data to file
    buffer.write(data.data(), data.size());
}

size_t get_file_size(const std::filesystem::path& file_path) {
    // Open file buffer for reading
    hexi::file_buffer buffer(file_path);

    if (!buffer) {
        return 0; // Return 0 if file open failed
    }

    // Get the size of readable data
    return buffer.size();
}
```

