#include <hexi/static_buffer.h>

template<size_t buffer_size = 1024>
struct BufferInfo {
    size_t capacity;
    size_t current_size;
    size_t free_space;
};

BufferInfo<> get_buffer_info(const hexi::static_buffer<std::byte, 1024>& buffer) {
    BufferInfo<> info;
    info.capacity = hexi::static_buffer<std::byte, 1024>::capacity();
    info.current_size = buffer.size();
    info.free_space = buffer.free();
    return info;
}

test cases:
#include <gtest/gtest.h>
#include <hexi/static_buffer.h>
#include <vector>

// Include the implementation
#include "implementation.hpp"

TEST(StaticBuffer, GetBufferInfo) {
    hexi::static_buffer<std::byte, 1024> buffer;
    std::vector<uint8_t> test_data(100, 0xAA);
    buffer.write(test_data.data(), test_data.size());

    auto info = get_buffer_info(buffer);

    EXPECT_EQ(1024, info.capacity);
    EXPECT_EQ(100, info.current_size);
    EXPECT_EQ(924, info.free_space);
}

TEST(StaticBuffer, GetEmptyBufferInfo) {
    hexi::static_buffer<std::byte, 1024> buffer;

    auto info = get_buffer_info(buffer);

    EXPECT_EQ(1024, info.capacity);
    EXPECT_EQ(0, info.current_size);
    EXPECT_EQ(1024, info.free_space);
}

TEST(StaticBuffer, CapacitySizeFreeRelationship) {
    hexi::static_buffer<std::byte, 1024> buffer;
    std::vector<uint8_t> data(50, 0xFF);
    buffer.write(data.data(), data.size());

    auto info = get_buffer_info(buffer);

    EXPECT_EQ(info.capacity, info.current_size + info.free_space);
}

