#include <gtest/gtest.h>
#include <hexi/shared.h>
#include <array>
#include <cstdint>

// Include the implementation
#include "implementation.hpp"

TEST(GenerateFilled, CreateFilledArray) {
    constexpr auto arr = create_filled_array<10>(0xFF);

    EXPECT_EQ(10, arr.size());

    for (const auto& element : arr) {
        EXPECT_EQ(0xFF, element);
    }
}

TEST(GenerateFilled, CreateFilledArrayZero) {
    constexpr auto arr = create_filled_array<5>(0x00);

    EXPECT_EQ(5, arr.size());

    for (const auto& element : arr) {
        EXPECT_EQ(0x00, element);
    }
}

TEST(GenerateFilled, CreateFilledArrayCustomValue) {
    constexpr auto arr = create_filled_array<8>(0x42);

    EXPECT_EQ(8, arr.size());

    for (const auto& element : arr) {
        EXPECT_EQ(0x42, element);
    }
}

TEST(GenerateFilled, VerifyFilledArray) {
    constexpr auto arr = create_filled_array<10>(0xAA);

    EXPECT_TRUE(verify_filled_array(arr, 0xAA));
    EXPECT_FALSE(verify_filled_array(arr, 0xBB));
}

TEST(GenerateFilled, LargeArray) {
    constexpr auto arr = create_filled_array<100>(0x55);

    EXPECT_EQ(100, arr.size());
    EXPECT_TRUE(verify_filled_array(arr, 0x55));
}

