#include <hexi/pmc/buffer_base.h>
#include <vector>
#include <cstddef>

class CustomBuffer : public hexi::pmc::buffer_base {
    std::vector<std::byte> data_;

public:
    /**
     * @brief Returns the current size of the buffer.
     * 
     * @return The number of bytes stored in the buffer.
