#include <hexi/pmc/buffer_read_adaptor.h>
#include <hexi/pmc/buffer_write_adaptor.h>
#include <vector>
#include <cstdint>

std::size_t write_multiple_chunks(const std::vector<std::vector<uint8_t>>& chunks) {
    // Calculate total size needed
    std::size_t total_size = 0;
    for (const auto& chunk : chunks) {
        total_size += chunk.size();
    }

    // Create a buffer with enough space
    std::vector<uint8_t> buffer(total_size);

    // Create write adaptor
    hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>> writer(buffer);

    // Write each chunk
    for (const auto& chunk : chunks) {
        // Check available space before writing
        std::size_t available = writer.free();

        if (available >= chunk.size()) {
            // Write the chunk
            writer.write(chunk.data(), chunk.size());
        }
    }

    // Return the total size written
    return total_size;
}

std::vector<uint8_t> read_partial_data(const std::vector<uint8_t>& buffer, std::size_t chunk_size) {
    // Create read adaptor
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> reader(const_cast<std::vector<uint8_t>&>(buffer));

    // Vector to store all read data
    std::vector<uint8_t> result;

    // Read until buffer is empty
    while (reader.size() > 0) {
        // Determine how much to read in this iteration
        std::size_t to_read = std::min(chunk_size, reader.size());

        // Temporary buffer for this chunk
        std::vector<uint8_t> temp(to_read);

        // Read the data
        reader.read(temp.data(), to_read);

        // Append to result
        result.insert(result.end(), temp.begin(), temp.end());

        // Check remaining data after read (size() returns remaining bytes)
        std::size_t remaining = reader.size();
        (void)remaining; // Use the size check as required
    }

    return result;
}
